SELECT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='avanzar_perdedor_nations' AND NOT tgisinternal) AS bronze_trigger_present,
 EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='guardar_plan_nations' AND p.prosrc LIKE '%third_place_match%' AND p.prosecdef AND has_function_privilege('service_role',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE')) AS private_optional_bronze_rpc,
 EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='avanzar_perdedor_nations' AND NOT p.prosecdef AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE')) AS private_loser_trigger_function;
